#include "mp3_player.hpp"

#include <hardware/clocks.h>
#include "hardware/dma.h"
#include "mcp4822.pio.h"  //auto-generated by CMakeLists
#include "pico/stdlib.h"

Mp3Player::Mp3Player(DAC_C DAC, double amplitude)
    : DAC(DAC),
      amplitude(amplitude),
      pio(pio0),
      offset(pio_add_program(pio, &mcp_4822_spi_program)),
      pio_config(mcp_4822_spi_program_get_default_config(offset)),
      sm(pio_claim_unused_sm(pio, true)),
      isPlaying(false) {
    buffer_1_needs_refill = true;
    buffer_2_needs_refill = true;
}

void Mp3Player::init() { return; }

uint16_t Mp3Player::mult_uint16_to_12(int16_t n16bits) {
    return static_cast<uint16_t>((static_cast<double>(n16bits) + 32768.0) / 65535.0 * 4095.0 *
                                 amplitude);
}

// using dma channels 0 and 1 /12
int data_chan_1 {0};
int data_chan_2 {1};
void Mp3Player::DMA_done_handler() {
    if (dma_hw->ints0 & (1u << data_chan_1)) {
        buffer_1_needs_refill = true;
        dma_hw->ints0 = (1u << data_chan_1);
        dma_channel_set_read_addr(data_chan_1, pcm_buffer1.data(), false);
        dma_channel_set_transfer_count(data_chan_1, outputSamps, false);
    }
    if (dma_hw->ints0 & (1u << data_chan_2)) {
        buffer_2_needs_refill = true;
        dma_hw->ints0 = (1u << data_chan_2);
        dma_channel_set_read_addr(data_chan_2, pcm_buffer2.data(), false);
        dma_channel_set_transfer_count(data_chan_2, outputSamps, false);
    }
}
void Mp3Player::play(MP3FrameInfo frame_info) {
    if (frame_info.samprate <= 0) { return; }
    isPlaying = true;
    outputSamps = frame_info.outputSamps;

    sm_config_set_out_pins(&pio_config, DAC.PIN_MOSI, 1);
    sm_config_set_sideset_pins(&pio_config, DAC.PIN_SCK);
    pio_gpio_init(pio, DAC.PIN_CS);
    pio_gpio_init(pio, DAC.PIN_SCK);
    pio_gpio_init(pio, DAC.PIN_MOSI);

    pio_sm_set_consecutive_pindirs(pio, sm, DAC.PIN_SCK, 2, true);
    pio_sm_set_consecutive_pindirs(pio, sm, DAC.PIN_MOSI, 1, true);

    sm_config_set_out_shift(&pio_config, false, true, 16);
    uint32_t pico_hz {clock_get_hz(clk_sys)};
    float div {static_cast<float>(pico_hz) / (2.0e6f * 2.0f)};  // 2MHz "SPI" since pio takes 2 cycles
    sm_config_set_clkdiv(&pio_config, div);
    pio_sm_init(pio, sm, offset, &pio_config);
    pio_sm_set_enabled(pio, sm, true);

    // DMA MACHINE
    // set up data channel 1
    dma_channel_config config1 = dma_channel_get_default_config(data_chan_1);
    channel_config_set_transfer_data_size(&config1, DMA_SIZE_16);
    channel_config_set_read_increment(&config1, true);
    channel_config_set_write_increment(&config1, false);
    channel_config_set_chain_to(&config1, data_chan_2);
    channel_config_set_dreq(&config1, 0x3b);  // 0x3b means timer0 (see SDK manual)

    dma_channel_set_irq0_enabled(data_chan_1, true);
    dma_channel_configure(data_chan_1,         // Channel to be configured
                          &config1,            // The configuration we just created
                          &pio->txf[sm],       // write address (SPI data register)
                          pcm_buffer1.data(),  // The initial read address. Equiv to &arr[0]
                          outputSamps,         // Number of transfers
                          false                // Don't start immediately.
    );

    // set up data channel 2
    dma_channel_config config2 = dma_channel_get_default_config(data_chan_2);
    channel_config_set_transfer_data_size(&config2, DMA_SIZE_16);
    channel_config_set_read_increment(&config2, true);
    channel_config_set_write_increment(&config2, false);
    channel_config_set_chain_to(&config2, data_chan_1);
    channel_config_set_dreq(&config2, 0x3b);  // 0x3b means timer0 (see SDK manual)

    dma_channel_set_irq0_enabled(data_chan_2, true);
    dma_channel_configure(data_chan_2,         // Channel to be configured
                          &config2,            // The configuration we just created
                          &pio->txf[sm],       // write address (SPI data register)
                          pcm_buffer2.data(),  // The initial read address. Equiv to &arr[0]
                          outputSamps,         // Number of transfers
                          false                // Don't start immediately.
    );

    // connect done interrupt to DMA_done_handler
    irq_set_exclusive_handler(DMA_IRQ_0, DMA_done_handler);
    irq_set_enabled(DMA_IRQ_0, true);

    // Get as close as possible to target sample rate
    double numerator {static_cast<double>(static_cast<int>(frame_info.samprate / static_cast<double>(pico_hz) * 65535.0))};
    double denominator {65535.0};
    double dma_samp_rate_frac {numerator / denominator}; // always under target samp rate
    double potential_samp_rate_frac {numerator / (denominator - 1)};
    const double target_fraction {frame_info.samprate / static_cast<double>(pico_hz)};
    while (potential_samp_rate_frac < target_fraction) {
        --denominator;
        dma_samp_rate_frac = potential_samp_rate_frac;
        potential_samp_rate_frac = numerator / (denominator - 1);
    }
    dma_timer_set_fraction(0, static_cast<uint16_t>(numerator), static_cast<uint16_t>(denominator));  // fraction of sysclock
    dma_start_channel_mask(1u << data_chan_1);  // begin dma
}

void Mp3Player::stop() {
    irq_set_enabled(DMA_IRQ_0, false);
    dma_channel_set_irq0_enabled(data_chan_1, false);
    dma_channel_set_irq0_enabled(data_chan_2, false);
    dma_channel_abort(data_chan_1);
    dma_channel_abort(data_chan_2);
    pio_sm_set_enabled(pio, sm, false);
}

void Mp3Player::add_PCM_to_queue(int16_t pcmBuffer[], MP3FrameInfo frame_info) {
    if (frame_info.samprate < 0) {
        return;
    }

    int channels{ frame_info.nChans };
    while (!buffer_1_needs_refill && !buffer_2_needs_refill) {
        busy_wait_us(0);
    }
    if (buffer_1_needs_refill) {
        for (int i = 0; i < frame_info.outputSamps; i++) {
            pcm_buffer1[i] = DAC::DAC_config_ON_regA |
                             mult_uint16_to_12(pcmBuffer[i]);
            if (channels == 2) {
                ++i;
                pcm_buffer1[i] = DAC::DAC_config_ON_regB | mult_uint16_to_12(pcmBuffer[i]);
            }
        }
        buffer_1_needs_refill = false;
    } else if (buffer_2_needs_refill) {
        for (int i = 0; i < frame_info.outputSamps; i++) {
            uint16_t data12bit{ mult_uint16_to_12(pcmBuffer[i]) };
            pcm_buffer2[i] = DAC::DAC_config_ON_regA | data12bit;
            if (channels == 2) {
                ++i;
                pcm_buffer2[i] = DAC::DAC_config_ON_regB | mult_uint16_to_12(pcmBuffer[i]);
            }
        }
        buffer_2_needs_refill = false;
    }
}